def split_long_unit(unit: str, target_len: int) -> list[str]:
    """段落本身超長（常見於docx擷取無換行的原始檔）時，改用中文句尾標點切句再組裝。"""
    if len(unit) <= target_len:
        return [unit]
    sentences = re.split(r"(?<=[。！？；\n])", unit)
    sentences = [s for s in sentences if s.strip()]
    out = []
    buf = ""
    for s in sentences:
        if len(buf) + len(s) > target_len and buf:
            out.append(buf)
            buf = s
        else:
            buf += s
    if buf:
        out.append(buf)
    return out


def chunk_text(text: str, target_len: int = 500) -> list[str]:
    paragraphs = [p.strip() for p in re.split(r"\n\s*\n", text) if p.strip()]
    units = []
    for p in paragraphs:
        units.extend(split_long_unit(p, target_len))
    chunks = []
    buf = ""
    for u in units:
        if len(buf) + len(u) > target_len and buf:
            chunks.append(buf)
            buf = u
        else:
            buf = (buf + "\n\n" + u) if buf else u
    if buf:
        chunks.append(buf)
    return chunks

