1	"use strict";
2	
3	// OpenClaw Hook：bni-member-directory-map
4	// 用途：bni_tainan 第一次收到新 LINE user ID 訊息時，查 LINE 顯示名稱，
5	//       比對通訊錄猜測真實姓名，寫進對照表，供教練查 user ID 是誰。
6	// 事件：message:received
7	// 軍師建立 2026-07-24 深夜（教練確認「非常需要」做成永久機制）
8	
9	const fs = require('fs');
10	const path = require('path');
11	const https = require('https');
12	
13	const HOME = process.env.HOME;
14	const MAP_FILE = path.join(HOME, '.openclaw', 'workspace', 'state', 'bni_tainan_line_id_map.json');
15	const TOKEN_FILE = path.join(HOME, '.openclaw', 'credentials', 'line-bni_tainan-token.txt');
16	const DIRECTORY_FILE = path.join(HOME, '.openclaw', 'agents', 'bni_tainan', 'knowledge', 'member_directory.md');
17	
18	function loadMap() {
19	  try {
20	    return JSON.parse(fs.readFileSync(MAP_FILE, 'utf8'));
21	  } catch (e) {
22	    return {};
23	  }
24	}
25	
26	function saveMap(map) {
27	  try {
28	    fs.mkdirSync(path.dirname(MAP_FILE), { recursive: true });
29	    fs.writeFileSync(MAP_FILE, JSON.stringify(map, null, 2));
30	  } catch (e) { /* silent */ }
31	}
32	
33	// 解析 member_directory.md 的 markdown table 行：| 姓名 | 專業 | 電話 | 合作對象 |
34	function loadDirectoryEntries() {
35	  try {
36	    const text = fs.readFileSync(DIRECTORY_FILE, 'utf8');
37	    const lines = text.split('\n');
38	    const entries = [];
39	    for (const line of lines) {
40	      const m = line.match(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*(09\d{8})\s*\|\s*([^|]+?)\s*\|$/);
41	      if (m) {
42	        entries.push({ name: m[1].trim(), profession: m[2].trim(), phone: m[3].trim(), target: m[4].trim() });
43	      }
44	    }
45	    return entries;
46	  } catch (e) {
47	    return [];
48	  }
49	}
50	
51	function guessMember(displayName, statusMessage) {
52	  const haystack = `${displayName || ''} ${statusMessage || ''}`;
53	  const entries = loadDirectoryEntries();
54	
55	  // 1. 完整姓名命中（最可信）
56	  for (const e of entries) {
57	    if (e.name.length >= 2 && haystack.includes(e.name)) {
58	      return { guessedMember: `${e.name}（${e.profession}）`, confidence: 'high_name_match' };
59	    }
60	  }
61	  // 2. 名字（去掉姓氏首字）命中——LINE暱稱常只打名不打姓，例如「柯朝陽」暱稱裡只有「朝陽」
62	  for (const e of entries) {
63	    const givenName = e.name.slice(1);
64	    if (givenName.length >= 2 && haystack.includes(givenName)) {
65	      return { guessedMember: `疑似${e.name}（${e.profession}，僅名字「${givenName}」命中，姓氏未確認）`, confidence: 'medium_given_name_match' };
66	    }
67	  }
68	  // 3. 專業類別詞命中（最弱訊號）
69	  for (const e of entries) {
70	    if (e.profession.length >= 2 && haystack.includes(e.profession)) {
71	      return { guessedMember: `疑似${e.name}（${e.profession}，僅專業關鍵字命中）`, confidence: 'low_profession_match' };
72	    }
73	  }
74	  return { guessedMember: null, confidence: 'unmatched' };
75	}
76	
77	function fetchLineProfile(userId, token) {
78	  return new Promise((resolve) => {
79	    const req = https.request({
80	      hostname: 'api.line.me',
81	      path: `/v2/bot/profile/${userId}`,
82	      method: 'GET',
83	      headers: { Authorization: `Bearer ${token}` },
84	    }, (res) => {
85	      let body = '';
86	      res.on('data', (chunk) => { body += chunk; });
87	      res.on('end', () => {
88	        try {
89	          if (res.statusCode === 200) resolve(JSON.parse(body));
90	          else resolve(null);
91	        } catch (e) { resolve(null); }
92	      });
93	    });
94	    req.on('error', () => resolve(null));
95	    req.end();
96	  });
97	}
98	
99	function isBniTainanLineDirect(event, ctx) {
100	  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
101	  return sessionKey.includes('bni_tainan') && sessionKey.includes('line') && sessionKey.includes('direct');
102	}
103	
104	function extractUserId(event, ctx) {
105	  const raw = event.from ?? event.senderId ?? ctx.from ?? ctx.senderId ?? '';
106	  let id = String(raw);
107	  if (id.startsWith('line:')) id = id.slice('line:'.length);
108	  if (!id) {
109	    const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
110	    const parts = sessionKey.split(':');
111	    id = parts[parts.length - 1] || '';
112	  }
113	  // 統一轉小寫存 key（跟 sessionKey 格式對齊），呼叫 LINE API 前另外轉大寫 U 開頭
114	  return id.toLowerCase(); // e.g. u895a0ad8e49d75f8303dc3d067282dc0
115	}
116	
117	const handler = async (event) => {
118	  if (!event || typeof event !== 'object') return;
119	  if (event.type !== 'message' || event.action !== 'received') return;
120	
121	  const ctx = event.context ?? {};
122	  if (!isBniTainanLineDirect(event, ctx)) return;
123	
124	  const userIdLower = extractUserId(event, ctx);
125	  if (!userIdLower) return;
126	
127	  const map = loadMap();
128	  if (map[userIdLower]) return; // 已記錄過，不重複查
129	
130	  let token;
131	  try {
132	    token = fs.readFileSync(TOKEN_FILE, 'utf8').trim();
133	  } catch (e) { return; }
134	
135	  const userIdForApi = 'U' + userIdLower.replace(/^u/i, '');
136	  const profile = await fetchLineProfile(userIdForApi, token);
137	  if (!profile) return;
138	
139	  const { guessedMember, confidence } = guessMember(profile.displayName, profile.statusMessage);
140	
141	  map[userIdLower] = {
142	    userId: userIdLower,
143	    displayName: profile.displayName || '',
144	    statusMessage: profile.statusMessage || '',
145	    guessedMember,
146	    confidence,
147	    firstSeenAt: new Date().toISOString(),
148	  };
149	  saveMap(map);
150	};
151	
152	module.exports = handler;
153	module.exports.default = handler;
154

