import re
text = open('/tmp/tool_defs.js').read()
# split roughly by 'id:' entries
blocks = re.split(r'\{\s*\"id\":', text)
for b in blocks[1:]:
    idm = re.match(r'\s*\"([a-z_]+)\"', b)
    profm = re.search(r'\"profiles\":\s*\[([^\]]*)\]', b)
    tid = idm.group(1) if idm else '?'
    profs = profm.group(1) if profm else '(none found)'
    print(tid, '->', profs)
"

