76	// === 語音訊息糾偏（E07，2026-07-24新增）===
77	// 不用關鍵字猜「陌生詞彙」(regex做不到語意判斷)，改用OpenClaw event本身的
78	// transcript/mediaType欄位——只要這則訊息是語音轉文字來的，就提醒糾偏四情況，
79	// 比猜關鍵字更精準（案例來源：BNI大台南會員多用LINE語音輸入，語音辨識容易諧音錯字）
80	function isVoiceMessage(c) {
81	  return !!(c && (c.transcript || c.mediaType === 'audio' || c.mediaType === 'voice'));
82	}
