"use strict";

// OpenClaw Hook：knowledge-search-inject
// 用途：任何 agent 若在自己的 scripts/knowledge_index.sqlite 建了 FTS5 全文檢索索引，
//       這支 hook 會在每則訊息送進LLM前，自動用訊息文字查詢索引，把最相關的知識庫
//       段落注入context——agent本身不需要、也不會拿到exec/write/edit工具權限。
// 事件：message:preprocessed（照 rule-reminder 模板）
// 注入：event.context.inject.push({ role:'system', content })
// 軍師建立 2026-07-26（教練指示：系統層面權限只有教練能動，public agent不該有exec/write，
//   但 jiaolian_thoughts 的知識庫搜尋原本靠agent自己呼叫exec——改成這支hook伺服器端執行，
//   agent完全不需要exec工具，缺口徹底關閉）

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const HOME = process.env.HOME;
const AGENTS_DIR = path.join(HOME, '.openclaw', 'agents');

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function parseAccountId(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');
  return agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
}

// 中文句子沒有空白分詞，直接把整句丟給search_knowledge.py的OR比對邏輯效果不好；
// 抽取2字以上的連續中文/英數詞塊當作查詢關鍵字，數量上限4個避免查詢過雜
function extractKeywords(text) {
  const matches = text.match(/[一-鿿]{2,6}|[a-zA-Z0-9]{2,}/g) || [];
  const seen = new Set();
  const out = [];
  for (const m of matches) {
    if (!seen.has(m)) { seen.add(m); out.push(m); }
    if (out.length >= 4) break;
  }
  return out;
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const ctx = event.context;
  const accountId = parseAccountId(event, ctx);
  if (!accountId) return;

  const scriptPath = path.join(AGENTS_DIR, accountId, 'scripts', 'search_knowledge.py');
  const dbPath = path.join(AGENTS_DIR, accountId, 'scripts', 'knowledge_index.sqlite');
  if (!fs.existsSync(scriptPath) || !fs.existsSync(dbPath)) return; // 這個agent沒建全文索引，靜默跳過

  const text = extractText(event);
  if (!text) return;

  const keywords = extractKeywords(text);
  if (keywords.length === 0) return;

  let output;
  try {
    output = execFileSync('python3', [scriptPath, keywords.join(' '), '--top', '2'], {
      timeout: 5000,
      encoding: 'utf8',
    });
  } catch (e) {
    return; // 搜尋失敗（索引壞掉/逾時等）靜默跳過，不影響對話
  }

  if (!output || output.includes('沒有找到相關內容')) return;

  const injection = [
    '📚 知識庫檢索結果（系統自動注入，供你回答時參考，不確定是否相關就自行判斷）：',
    output.trim(),
  ].join('\n\n');

  if (!ctx.inject) ctx.inject = [];
  if (Array.isArray(ctx.inject)) {
    ctx.inject.push({ role: 'system', content: injection });
  }
};

module.exports = handler;
module.exports.default = handler;

